cat > index.js <<'EOF'
const fs = require('fs');
const path = require('path');

const readme = fs.readFileSync(path.join(__dirname, 'README.md'), 'utf8');
const headings = readme
  .split('\n')
  .filter((line) => line.startsWith('#'))
  .join('\n');

fs.writeFileSync(path.join(__dirname, 'INDEX.md'), headings + '\n');
EOF
node index.js
cat INDEX.md
